import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易經傳集解卷三十一","description":"周易經傳集解 - 周易經傳集解卷三十一","frontmatter":{"title":"周易經傳集解卷三十一","description":"周易經傳集解 - 周易經傳集解卷三十一"},"headers":[],"relativePath":"classics/jingchuan-jijie/032.md","filePath":"classics/jingchuan-jijie/032.md"}'),r={name:"classics/jingchuan-jijie/032.md"};function c(o,a,l,d,p,j){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易經傳集解卷三十一",tabindex:"-1"},[n("周易經傳集解卷三十一 "),e("a",{class:"header-anchor",href:"#周易經傳集解卷三十一","aria-label":"Permalink to “周易經傳集解卷三十一”"},"​")],-1),e("p",null,"欽定四庫全書周易經傳集解卷三十一 ​宋林栗撰序。卦曰：節之信之，故受之以「中孚」。中孚成卦，節之變也。自節之中孚變上六一爻而成也。以六居上，則剛柔分；以九居上，則柔在內；而二、五剛中，則其所同也。剛柔分而剛得中，所以能「亨」也。說以行險，所以為節；說而巽，所以為孚也。節至上六，節之苦也。苦節不可貞，是以變之而後孚也。人之常情，樂放肆而苦拘檢，誇侈靡而陋儉約，則雖剛柔分而能節，苟無以信之，亦不可得而節矣。孔子曰：「信而後勞其民，未信則以為厲己也。」故節之序曰：「節而信之，猶革之彖曰革而信之也。」世之君臣，或喜於有為，見弊則思革，觀甚則思節。然而每每多敗而少成者，皆無以信之故也。中孚：豚魚吉，利涉大川，利貞。彖曰：「中孚」，柔在內而剛得中，說而巽，孚乃化邦也。「豚魚吉」，信及豚魚也。「利涉大川」，乘木舟虛也。「中孚」以「利貞」，乃應乎天也。下兌上巽成卦曰「中孚」者，初為兌，二為震，三為艮，四為巽。兌，說也；巽，入也。說而巽乎孚，何也？謂其有震、艮之象焉。震為春，巽為夏，兌為秋，艮為冬。「巽」者，震之配也，四時行焉，百物生焉，是以謂之孚也。孚者，信而化之之謂也。國之治教正刑，如寒暑四時之序，則民信而化之矣。巽之於震，兌之於艮，其孚之也，不亦宜乎？然則名卦為孚，於義既備，而必系之以「中」者，何哉？曰：此聖人所以示之也。記不云乎：「喜怒哀樂之未發，謂之中；發而皆中節，謂之和。」中者，誠也。孚者，化也。惟天下之至誠為能化，此其所以本之於「中」歟？故子曰：「中孚，柔在內而剛得中，說而巽，孚乃化邦也。」柔在內，謂三四也。剛得中，謂二五也。自「渙」、「兌」、「節」，皆剛中而柔外。剛，君也；柔，臣民也。剛雖中而柔尚外，則其孚未至也。至是柔在內而剛得中，則是自西自東，自南自北，無思不服也。而上下二剛，有「兌」、「巽」之象焉，則天下之從我者，皆說其「巽」矣。謂之「孚」也，不亦宜乎？「中孚，豚魚吉」，何謂也？曰：古之為政，山不槎櫱，澤不伐天，魚禁鯉鮞，獸長慶䴠，鳥翼卵，蟲含蚳䖶，蕃庶物也。先王交萬物有道，自奉養有節，伐一草木，殺一禽獸，必以其時。故雖豚魚之微，亦信其有仁愛之心焉。詩曰：「敦彼行葦，牛羊勿踐履。方苞方體，維葉泥泥。」而序之者曰：「周家忠厚，仁及草木。」夫仁及草木者，非謂其不剪伐也，謂其方苞方體而使之得以遂其生也。然則信及豚魚者，豈非鯤鮞麑䴠得以滋息而無夭閼之虞哉？記曰：「惟天下至誠，為能盡其性，能盡其性，則能盡人之性，能盡人之性，則能盡物之性，能盡物之性，則可以贊天地之化育。」中孚之謂矣。「利涉大川」何謂也？曰：全卦之體有虛舟之象，上下二體以巽成兌，巽為木、為風，兌為澤，故有乘木涉川之象。乘木以涉川，其覆溺者必重載也，舟虛則無虞矣。君子之遊於世，如虛舟漂而不沉，觸而不怒。我不害物，物亦信而不吾害；我不疑物，物亦信而不吾疑，斯可以行乎患難矣。「利貞」何謂也？曰：中孚者，物之所以成始也；利貞者，物之所以成終也。為備震、巽、艮、兌之體，是以系之「利貞」之辭焉。天之於物也，春生之，夏長之，秋收之，冬藏之。聖人之於物也，元以育之，亨以通之，利以和之，貞以固之。故子曰：「中孚以利貞，乃應乎天也。」說者於乾四德，皆以應四時，蓋文言著矣。而中孚以利貞，無文言以考，故皆用卦氣之論，以中孚為冬至之氣。自揚雄作太玄，首中以準中孚，其說曰：「陽氣潛萌於黃宮，信無不在乎中。」推其意，蓋取中孚剛中之義，而為陽氣潛萌之論，以謂中孚者，信出於中而已。夫仁義禮智，孰非出乎中者，而必信之云乎？既取諸剛中，而為陽氣潛萌之論，則所謂柔在內者，將安取之乎？程氏曰：「中虛者，信之本；中實者，信之質。」本之與質，愚未知其所以別之也。夫孚之訓信也，非有諸己而名之也，上下交相信，然後謂之孚也。故子曰：「豚魚吉，信及豚魚也。」謂王化之所孚，不特兆民信之，鳥獸魚鱉皆信之矣。按：中孚與小過反對而成，中孚有鳥卵之象，而小過有飛鳥之象焉。何則？中孚之柔包藏於內，而小過之柔發見於外也。是故孚之於文，以瓜覆子，羽蟲之字卵是也。夫爪牙之利，鳥獸之所為搏噬也，而能覆其輕脆之卵以成變，以正性命，豈非其內外相信而後然歟？苟其中之不愛，未有不毀而去之者也。是故中而後孚，孚而後利，利而後正，應天之義，可得而言之矣。堯典於春言「鳥獸孳尾」，於夏言「鳥獸希革」。孳之言字也，「革」之言變也，應其時義矣。故曰：「善言天者，必有驗於人；善言古者，必有驗於今。」而為卦氣之論者，乃以應冬至之候，則其言「利貞」「應天」之義，不已疏乎？愚不自揆，輒於復卦論六日七分之非，而於中孚辨卦氣之誤，將以俟明者而質焉。象曰：澤上有風，中孚，君子以議獄緩死。「澤」者，兌也。風者，巽也。水鍾於澤，而風過之，則水草以之蕃滋，蠱魚以之生息，風之所化。王者當天地長養之時，禁民毋覆巢，毋伐木，毋竭川澤，毋漉陂地，毋焚山林，草木鳥獸魚鱉鹹得以遂其生。及其取之也有節，用之者有禮，則鳥獸魚鱉亦莫不孚知夫邊豆庖廚之不可已，非樂於多殺矣。君子觀此之象，凡民之有罪而麗於獄者，從而議之，若周官八議之類，求所以生之，而去其甚者矣。其惡積而不可揜，罪大而不可解者，亦姑緩之以盡其情，而示其有所不忍之心焉。然後民之死者，皆知其自入於刑，而非君子之慾殺之也。故書稱「好生之德，洽於民心，克寬克仁，彰信兆民」。至於仁及草木，恩被動植，皆中孚之義也。雜卦曰：「中孚，信也。」中孚為卦，以羽蟲字卵而成。其在六爻，以信而後孚為義。傳曰：「同言而信，信在言前；同令而行，誠在令外。」是故孚之成卦，四陽二陰。六三之所孚者，九二、上九也。六四之所孚者，九五、初九也。三應在上，而比於二；四應在初，而比於五。然六二有在陰之和，九五有「攣如」之孚，初九「有他」而「不燕」，上九「登天」而貞兇。彼不孚其所應，而孚其所比者，何哉？其必有以信之矣。所以然者，二五剛中，初上剛而不中故也。然古之化明者，其始曷嘗不以言？及乎教化之成，則有不言而信者矣。是故九二「鳴鶴在陰」，而和之者「或鼓或罷，或泣或歌」；九五「有孚攣如」，而從之者亡其匹而絕其類矣。子曰：「擬之而後言，議之而後動。」擬議以成其變化，九二之謂也。「默而成之，不言而信，存乎德行」，九五之謂矣。中庸曰：「聲色之於以化民，末也。上天之載，無聲無臭，至矣！」是「中孚」之義也。初九：虞吉，有他不燕。象曰：「初九虞吉」，志未變也。初九，「兌」也。以陽居剛而在下卦之下，應乎六四。四，「艮」「巽」也。故曰「虞吉」。虞，度也。書雲「若虞機張」是也。初應在四，而九五在上，初苟不虞於五，而欲有其應，則所不度德、不量力，幾何而不危辱哉？故曰：「有他不燕」。燕，安也。初體正而居下，自度其德非五之敵，而安守臣節，不敢與五爭民，斯保其能吉矣。苟有他志，非所以為安也。故子曰：「初九虞吉，志未變也。」為其下而居初，其志未變也，故免於不虞之咎，而得自全之吉矣。若翰音登於天，則其兇不可逃也。九二：鳴鶴在陰，其子和之。我有好爵，吾與爾靡之。象曰：「其子和之」，中心願也。九二，「震」也，以陽居柔，而下卦之中，上旡其應，而承於六三。三，「艮」「巽」也，故曰：「鳴鶴在陰，其子和之。」震為喜鳴，又為鵠，故有「鳴鶴」之象。以九居二，故有「在陰」之象。承於六三體「巽」，以「巽」從震，故有「其子和之」之象。夫「巽」之於「震」，男女皆長也，以為夫婦則可矣，而謂之子，何哉？曰：君臣也，父子也，夫婦也，其象無乎不通，惟其所取如何耳。「震」，木也；「巽」，木火也。「震」，東也；「巽」，東南也。以木生火而傳之，父子之象也。「中孚」成卦，以羽蟲子卵而成，則三、四二爻謂之子，宜矣。鶴，陽鳥也，鳴而在陰，將以習其子也。故曰：「我有好爵，吾與爾靡之。」靡，或本作靡，散也。陽為實，陰為虛。九二自謂我有好爵，將與爾散之，欲其子之和之也。故子曰：「其子和之，中心願也。」「中心願」者，其九二之情乎！所以然者，二雖剛中，為未當其位，三雖柔巽，而有應在上，故其向背從違，特未定也。然則古之人所以化導其民，惟恐其不至者，亦猶鳴鶴之願其子乎？說者皆以為和者中心之願，愚謂不然。卦唯二、五為中，九二居尊，非二之所得而子也。誠其中心之願，則無我有好爵之辭矣。擬之而後言，議之而後動，擬議以成其變化，其此之謂歟？子曰：君子居其室，出其言善，則千里之外應之，況其邇者乎？居其室，出其言不善，則千里之外違之，況其邇者乎？言出乎身，加乎民；行廢乎邇，見乎遠。言行，君子之樞機。樞機之發，榮辱之王也。言行，君子之所以動天地也，可不謹乎？鶴者，君子之譬也。居其室者，在陰之譬也。出其言者，鳴之譬也。然其善不善，應不應，未可知也。二之言曰：「我有好爵，吾與爾靡之。」六三，或鼓或罷，或泣或歌。則其爾者，或未必應矣。古今言易者，皆以九二一爻為中孚之至盛，失之矣。中孚之化，不言而信。九二以言勝人者也，焉得為至盛乎？以為教化之未孚，若周公之多誥，盤庚之籲民，則無失其義矣。六三：得敵，或鼓或罷，或泣或歌。象曰：「或鼓或罷」，位不當也。六三上體為「艮」，下體為「巽」，以陰居剛，而在下卦之上，應上九之「兌」，而乘九二之震，故曰「得敵」。春秋傳曰：「嘉耦曰妃，怒耦曰仇。」仇，敵也。六三之於上九，有「艮」、「兌」之合焉。然三以柔而體「艮」，上以剛而體「兌」，「兌」反居上，「艮」反居下，是以謂之敵也。故曰：「或鼓或罷，或泣或歌。」「震」為鳴，故有「或鼓」之象。「艮」為止，故有「或罷」之象。「兌」為口舌，「巽」為進退，為不果，故有「或泣或歌」之象。六三當「中孚」之時，近於九二，宜不約而孚矣。然以柔乘剛，不當其位，又有上九為之應焉，是以鼓罷泣歌之無常也。故子曰：「或鼓或罷，位不當也。」惟其位之不當，是以不安其分，躁妄而求，兇之道也。然爻不言兇者，為其近於九二，幸其和之，則免於兇矣。是以九二、六三但言君子小人之情狀，而不著其吉凶。至於「翰音登於天」，然後系之兇也。六四，月幾望，馬匹亡，無咎。象曰：「馬匹亡」，絕類上也。六四上體為「巽」，下體為「艮」，以陰居柔，而在上卦之下，應初九之「兌」，而承九五之「震」，故曰：「月幾望，馬匹亡。」「月」，陰物也；馬，陽也。人臣之義，譬如月焉，受日以為明者也；譬如馬焉，任重而致遠者也。六四上承九五，以「巽」遇震，故有月望之象；下應初九，以艮遇兌，故有馬匹之象。月之既望，則盈而將虧矣；馬之過匹，則逸而泛駕矣。四當中孚之時，居近君之位，上攣於五，而下絕於初，故於月為幾望，於馬匹亡矣，故曰「無咎」。月幾望，望則無虧損之變；馬亡其匹，則無奔軼之虞，是以系之無咎也。或曰：四於初為正應，烏知其絕之歟？曰：孚者，化也，陰陽合而化生也。是故陰之情慾升，陽之情慾降，然後為孚之時也。六三之於九二，所以鼓罷泣歌之無常者，正以其位之不當，而升降之殊情耳。六四在上，初九在下，其絕之也，不亦宜乎？故子曰：「馬匹亡，絕類上也。」為臣之奉公而無私，得主而喪朋，斯為無咎矣。或曰：初九以剛而體兌，六四以柔而體艮，其謂之類，何也？曰：兌與艮為匹，而於巽為類矣。爻言匹而象言類，互明之也。曰：若是，則君子之得君子也，不與其類並進已乎？曰：非此之謂也。君子和而不同，周而不比，見善而稱，知賢而舉，豈特比而同之哉乎？曰：「天地絪縕，萬物化醇，男女媾精，萬物化生」，言致一也。苟無致一之誠心，而二三其德，唯利是從，欲上下之交孚，難矣！此聖人之所以戒之也，非謂其不可引類而聚於王朝也。夫言各有當，易稱「比吉」，而子曰：「君子周而不比。」「同人亨」，而子曰：「君子和而不同。」「利者義之和」，而子曰：「小人喻於利。」是皆文同而義異，不可以害其辭旨也。九五：有孚攣如，無咎。象曰：「有孚攣如」，位正當也。九五，「震」也。以陽居剛，而在上卦之中，下無其應，而乘乎六四。四，「艮」巽也，故曰「有孚攣如，無咎」。中孚六爻唯五為「有孚」者，則剛健中正，不言而信，孚之至也。易以異體之合為「交如」，同體之合為「攣如」，有牽攣固結之義也。四為巽，五為震，剛中而柔內，剛上而柔下，雷風相與，「巽」而動，是以其孚牽攣固結之義可解也。然而不繫之吉，而但言「無咎」者，下無正應故也。若以六居二，則「有孚惠心，勿問元吉」矣。變孚之二，得益之象，豈不然哉？若大有九二與六五為應，亦曰「厥孚交如，威如，吉」也。今九五、六四君臣相孚，有「攣如」之象，然其孚未及乎天下，是以但言「無咎」而已。小畜之九五曰：「有孚攣如。」亦以六四之臣與之合志，而無咎之辭繫於陰爻也。然「小畜」四、五兩言「有孚」，而「中孚」獨言於五者，彼以「小畜」成卦，非兩言其孚不足以明六四之志；此以「中孚」成卦，獨言於五，而四之義該矣。故子曰：「有孚攣如，位正當也。」唯其位之正當，是以君不置疑於其臣，臣不避嫌於其君，然後為「中孚」之至也。九：翰音登於天，貞兇。象曰：「翰音登於天」，何可長也？上九，「兌」也，以陽居柔，而在上卦之上，應乎六三。三，「艮」「巽」也，故曰「翰音登於天」。「翰音」，雞也。禮：雞曰翰音。五上，天位也。「巽」為雞而應於上九，故有「翰音登天」之象。夫雞者，仰而號，俯而啄，飛乎枋榆之下，而鳴於牆屋之間，是其智力之所及也。雞而欲登天，非其任矣，故曰「貞兇」。以此為「貞兇」。求其和，六三之「巽」，乘於九二之震，二鳴於陰，以求其和，宜若與之交孚矣。然為其柔上而剛下，故三不順於二，自以體「艮」而欲應於上。上九之「兌」，澤上於天，既不可以居矣，六三又從而從之，小人相與覬覦非望，是以有「翰音於天」之象也。故子曰：「翰音登於天，何可長也。」飛龍在天，豈雞之任哉？說者或以「中孚」既有鳥卵之象，則翰音登天，是卵翼而飛鳥矣。若如所論，何自兇哉？序卦曰：「有其信者必行之，故受之以小過。」「小過」，「中孚」之變也。自孚之過，兌變為「艮」，巽變為「震」，六爻盡易而成也。震與巽艮配也。剛柔相信，然後志合而道行。故「中孚」以巽兌而含震艮，以四陽而包二陰；「小過」以震艮而合巽兌，以四陰而包二陽，明其志合而道行也。行而謂之「過」，何也？曰：世方承平，則常得乎中道；及其矯枉救弊，則不能無過於常，此過之所以為行也。是故有「小過」，有「大過」，陽為大，陰為小。「大過」者，陽過乎陰，四陽而二陰也；「小過」者，陰過乎陽，四陰而二陽也。然「頤」之四陽，曷不為「小過」？「中孚」之四陽，曷不為「大過」乎？曰：「過」之為言，過常以適變者也。唯外柔而內剛者，能通變以行權；柔內而剛外者，非其任也。故「頤」四陰二陽，取口實之象；「孚」二陰四陽，取卵化之象。「頤」之序曰：「不養則不可動，故受之以大過。」「孚」之序曰：「有其信者必行之，故受之以小過。」是則所謂「過」者，非徒過越而已。君子之有所動，有所行，過常而適變之義也。不有其信，其何以行之哉？此「小過」之所以次「中孚」也。小過：亨，利貞。可小事，不可大事。飛鳥遺之音，不宜上宜下，大吉。彖曰：「小過」，小者過而亨者。過以「利貞」，與時行也。柔得中，是以小過吉也。剛失位而不中，是以不可大事也。有飛鳥之象焉，「飛鳥遺之音，不宜上，宜下，大吉」，上逆而下順也。下艮上震成卦曰小過者，初為艮，二為巽，三為兌，四為震。震，動也；艮，止也。「時止則止，時行則行」，謂之小過，何也？為其有巽、兌之象焉。震，長男也；巽，長女也；艮，少男；兌，少女也。震居三四而失其位，巽居二五而執其權，是以為小者之過也。震為雷，巽為風，艮為山，兌為澤。雷風鼓舞于山澤，而草木鳥獸魚鱉之生以遂。然其所振動，不能無小有所過焉，是以謂之小過也。「小過，亨利貞」，何謂也？曰：小過有震、巽、艮、兌之體，則宜有「元亨利貞」之辭。然中孚有卵化之象，小過有飛鳥之象，鳥飛則羽翼既成矣，是以不繫之元，而但云「亨利貞」也。聖人之道，極乎中庸，過與不及，其失均也。然而治教政刑，每有偏而不起之處。世之君子，苟欲起而救之，必待小有所過，然後能反俗之弊，而歸之於中庸。是則雖謂之過，乃時中也。因世俗耳目之所不常見，而謂之過耳。是故大者過，謂大事之過也，亦謂尊者之過也。小者過，謂小事之過也，亦謂卑者之過也。或謂小者為小人，非也。小人不可一日用於天下，聖人之戒，深切著明矣，況其過越而亨乎？能大事之過，將以撥亂而反正也。小事之過，將以矯弊而適中也。尊者之過，君驕而臣諛也。卑者之過，臣強而主弱也。君矯臣諛，故以「棟撓」象之。臣強主弱，故以「飛鳥」象之。然以其剛過而得中，故謂之「大過」；以其柔過而得中，故謂之「小過」也。君子過言則民作辭，過動則民作則。過乎恭所以矯其慢，過乎哀所以矯其易，過乎儉，所以矯其奢，過之所以為「亨」也。然恭不至於辱，哀不極於毀，儉不入於陋，過之所以為「利貞」也。貞者，正也。君子之矯在救弊，期於正而已矣。故子曰：「小過，小者過而亨也。過以利貞，與時行也。」寒往則暑來，暑往則寒來，以震代艮，以兌繼巽，其「與時偕行」之象乎？損之彖曰：「二簋應有時，損剛蓋柔有時，損益盈虛，與時偕行。」夫亨至於二簋，可謂過乎儉矣。然與時偕行，不為過也。譬如冬裘夏葛，非其時而服之，得不謂之過乎？「可小事，不可大事」，何謂也？曰：小過陰居二五，柔得中也。柔得中者，臣不失其道也。臣不失其道，則凡欲驕枉而救弊，事之小者可為也。陽居三四，則失位而不中也。剛失位而不中者，君失其道也。君失其道而臣得之，苟欲大有所為，不幾於作福作威者乎？是以不可大事也。聧之六五得中，亦曰「小事吉」。豐之九三不中，亦曰「不可大事」也。「飛鳥遺之音，不宜上宜下，大吉」，何謂也？曰：小過有飛鳥之象焉。二陽在內，為腹背之象；四陰在外，為羽翰之象。鳥之飛止，不在腹背，而在於羽翼，則是君無為而臣用事之譬也。鳥飛在上，而遺音在下，則是位高而名盛之譬也。震為善鳴，故有遺音之象。鳥，逆而上者也，愈上則其勢愈逆，將無以託其足而蔑其音；下則其勢順，斯有以安其身而全其名。故曰：「不宜上，宜下，大吉」，上逆而下順也。下則為伊、周，上則為莽、卓也。伊尹之復政厥闢，周公之復子明辟，皆鳥飛而能下者也，可不為大吉乎？夫大權不可久執，大名不可久居。處人臣之極，任天下之重，未必皆有還政復辟之事，但能謙恭卑巽，畏遠權勢，則可以保其富貴而全其令名，亦下之義也。是以周公既復辟，北面就臣位，鞠躬如畏然，得其道矣。夫周公以叔父之親，居宰執之尊，至於鞠躬如畏，不亦過乎恭者哉？然勢疑則隙生，位高而毀至，不若是不可也。其亦與時行之義乎？象曰：山上有雷，小過，君子以行過乎恭，喪過乎哀，用過乎儉。山者，艮也。雷者，震也。雷行天下，無所不震。今雲「山上有雷」，是雷久居於山也。雷久于山，山之草木鳥獸將有震而僵斃者，得不謂之過乎？然其過小，其發生之功大，是以謂之「小過」也。君子之所為驚世駭俗之行，以新起斯民耳目者，凡皆以趨變而矯弊也，則復其亦若此也。然過趨變之事，不止於恭、哀、儉，而特言是三者，蓋人之過，各於其黨，君子之過，常過乎厚。是三者，君子之過也。陳司敗問昭公知禮乎？孔子曰：「知禮。」司敗遂疑其黨，而夫子亦自受其過，是則過乎恭也。當是之時，訕上之俗成，慢君之風靡，安得不小有所過以救之與？是以夫子入公門，鞠躬屏氣，升降踧踖，事君盡禮，人以為謟，不亦小過之義乎？至若正考父三命盡，循牆而走，曾子水漿不入口七日，宴子一狐裘三十年，未必皆過也。君子所以矯世俗之弊，引之於常道而止也。雜卦曰：「小過，過也。」小過成卦，以四陰過二陽而成共。在六爻以過與不及為義。過乎九三者，六二、上六也；過乎九四者，六五、初六也。然六二之於九三，九四之於六五，多寡適平，無以相過。唯初六、上六，則過之遠矣。人臣之勢，遠過於君，豈能久而無變也？是以初、上皆有「飛鳥」之兇，而六二、九四之「無咎」，九三之「兇」，六五之「不雨」，皆以相過、不及而取之耳。夫「大畜」、「小畜」，皆「畜」也；「大過」、「小過」，皆「過」也。而雜卦曰：「大畜，時也；小畜，寡也。大過，顛也；小過，過也。」苟非以六爻相雜，即其時也，以求其義，而強欲通之，未能有為之說者也。初六：飛鳥以兇。象曰：「飛鳥以兇」，不可如何也。初六，「艮」也，以陰居剛，而在下卦之下，承於六二之「巽」，而應乎九四。四，「震」「兌」也，故曰「飛鳥以兇」。「以」，用也。春秋傳曰：「凡師能左右之曰以。」「小過」有飛鳥之象，初六則其羽翰也。「震」為動，「艮」為止，「兌」為說。「震」動而「艮」之，「兌」說而從之，是四之動靜之權，是身輕而羽重也，故有「飛鳥以之」之象。鳥為翰之所「以」，猶君為臣之所「以」也。為君而見以於臣，則生殺予奪皆出其手，欲無兇，得乎？書曰：「臣之有作福作威，其害於而家，兇於而國。」斯之謂也。故子曰：「飛鳥以兇，不可如何也。」言臣下專恣，左則欲左，右則欲右，為其上者，無如之何也，其兇宜哉！六二：過其祖，遇其妣；不及其君，遇其臣。無咎。象曰：「不及其君」，臣不可過也。六二，「巽」也。以陰居柔而在下卦之中，上無其應，而承乎九三。三，「震」也，「兌」也。故曰：「過其祖，遇其妣；不及其君，遇其臣。」二承乎三，三有君父之象焉。二承乎四，四之於二，則其祖矣。初應乎四而連於三，配祖則為妣，從君則為臣也。夫陰陽適稱則為平，偏勝則為過。六二之於九四則過之，以是「過其祖」也。陽為有餘，陰為不足，六二之於九三，則弗過矣，是「不及其君」也。相違為「暌」，相值為「過」。六二之於初六，則過之矣，是「過其妣，遇其臣」也。夫君臣、父子、夫婦之際，尊卑之分，必致其嚴也。故子不可以過於父，臣不可以過於君，婦不可以過於夫，懼其憑陵而至於僭越也。若夫祖之與孫，則尊卑隔絕矣，雖過之而無嫌也。豈獨無嫌，乃祖之所以願於孫也。故禮曰：「君子抱孫不抱子。」孫可以為王人屍，子不可以為父尹。為人子者，不敢以富貴加於父兄。至於子，則欲其無忝而已，況又過其妣乎？遇者，相得之謂也。過祖而遇妣，祖之所不怒也。若過君而遇其臣，則君不能堪矣，曰「無咎」。初六於曰為悍妻，於三為強臣，二與之遇，宜若有咎矣。然二過祖而遇妣，則祖妣不失其愛；不及君而遇其臣，則君臣不失其歡，是以為「無咎」也。所以然者，二中正而柔順故也。以「巽」從「震」，又何咎之有哉？六二一爻居祖妣君臣之間，不過其祖則為不肖，不遇其妣則為不順。過其君則為不臣，不遇其臣則為不和。有一於此，兇咎隨之。而象止曰「不及其君，臣不可過也」，蓋舉一隅以待三隅之反耳。九三：弗過防之，從或戕之，兇。象曰：「從或戕之」，「兇」如何也？九三上體為「兌」，下體為「震」，以陽居剛，而在下卦之上，應上六之「艮」，而乘六二之「巽」，故曰「弗過防之」。以九居三，不得其中，可謂過乎剛矣。然卦以小過為義，三非小也，故取諸陰爻而言「弗過」。「弗過」者，為六二言之也。六二居柔而承剛，體「巽」而從震，中正而在下，則其道矣。為其陰陽偏勝，宜若過焉。然方於九三，是乃不及，非過之也。三又以「兌」而應「艮」，「艮」為土，故有隄防之象。六二於三不為過，而三過以防之，民時不直其上也，故曰：「從或戕之，兇。」二弗過而三不能容，三過防而二不能堪，君臣不相安，必有大變。然六中正柔巽，終無犯上作亂之事。而三之從者，或從其事矣，則人君忌刻而強愎，無故而疑大臣，則其刑威殺戮，必將不得其中，而左右近習之習，將懼誅而作難矣，故或之。在內曰弒，在外曰戕，不測之變也。震為木，兌為金，震為決躁，兌為毀折，故有從或戕之象。晉靈公之事是已。春秋之世，晉有六卿，魯有三家，蓋小過之時也。趙盾雖強家，盾之為臣也，恭欽而忠順，不為過也。靈公使賊殺之，伏甲攻之，嗾犬噬之，可謂甚矣。盾終不敢萌逆節，而穿實殺之，所謂「從或戕之」者矣。晉悼公、魯昭公，亦九三之居也，而欒民、季孫，皆非六二之臣，故不得待其從而自為之矣。昭公之免於弒者，㓙也，爻之稱不亦宜乎？故子曰：「從或戕之，兇如何也？」孔子親見當時之事而盛爻繇之辭，故深嘆其兇，言從者猶或戕之，則其㓙咎之形宜如何也。此與鼎之九四「覆公餗，信如何也」，辭旨略同。或曰：六二不及其君而遇其臣，故爻言「無咎」。今九三既成於兇，則二得為無咎乎？曰：吉凶無常，惟人所召。二為之臣，可以無咎，而三成於「兇」，則不得為無咎矣。然則趙盾亡而越竟，反而討賊，庶其免乎？故夫子嘆之曰：「惜也！」越竟乃免。九四：無咎。弗過遇之，往厲必戒，勿用永貞。象曰：「弗過遇之」，位不當也；「往厲必戒」，終不可長也。九四上體為「震」，下體為「兌」，以陽居柔而在上卦之下，應初六之「兌」而承六五之「巽」，故曰「無咎」。剛失位而不中，宜若有咎矣，為其與六五遇，剛柔相濟，多寡適平，斯為無咎矣，故曰「弗過遇之」。「小過」之世，臣過乎君。今六五以陰居剛，而九四以陽居柔，有巽震之合焉，則不為過而為遇矣。君臣相遇，宜若可以有為，然小過之時，有君弱臣強之象，往而不戒，有危道焉。象之所謂「可小事，不可大事」也。故曰：「往厲必戒，勿用永貞。」貞者，正也。剛下而柔上，下震而上巽，非恆久之道，而又下應於初，有「鼎折足」之象，非特不可以大有為，將不宜永以為正也。故子曰：「弗過遇之，位不當也。」為其不當也，是以上承六五，不為遇而為過矣。「往厲必戒，終不可長也。」履霜堅冰，其斯之謂與？姤之彖曰：「勿用取女，不可與長也。」其二曰：「有攸往，見兇。」聖人見機而知著，垂戒深切，皆此類也。六五：密雲不雨，自我西郊。公弋取彼在穴。象曰：「密雲不雨」，已上也。六五，「巽」也，以陰居剛而在上卦之中，下無其應，而乘乎九四。四，「震」「兌」也，故曰：「密雲不雨，自我西郊。」雲雨者，「坎」之象也。四為「震」，五為「巽」，而系之雲雨，何哉？曰：震為雷，「巽」為風，雷震則雲興，風行則雨至也。然陰陽和而後雨，陰猶未離其類，則為「密雲」而已。夫「震」之於「巽」，六五之於九四，有相求之義，宜其相與為雨矣。然四而「兌」焉，「兌」為西，西郊，陰之所也。其為「密雲」而不雨，不亦宜乎？所以然者，九四之「兌」，下應於初六之「艮」，則其從五之志，未能尊一，是以「密雲」而「不雨」也。「東北喪朋，乃終有慶」，其是之謂乎？故曰：「公弋取弋在穴。」五為王，四為公。「弋」，繳射也。「巽」為繩，「兌」為金，故有弋射之象。「艮」為黔啄之屬，而在下卦之下，故有在穴之象。蘇氏曰：「權臣用事，必有穴其間而為之用者，莫若取以自明於天下，而天下信之矣。」楚使薳子馮為令尹，有寵於薳子者八人，皆元祿而多馬。他日朝，與申叔豫言，不應。子馮請焉，申叔曰：「吾懼不免。」薳子辭八人者，而後王之，亦取彼有穴之義也。故子曰：「密雲不雨，已上也。」雲也，上之天也，離其類而之乎東北，則其施下矣。「小畜」之彖曰：「密雲不雨，自我西郊。」亦「巽」、「兌」之象也。「小畜」以臣畜君，其密為雲而不雨者，尚往而未復也。「小過」以臣過君，其為「密雲」而不雨者，已上而未下也。君子之慾致其君而膏澤下於民者，可不思「喪朋」之義哉？上六：弗遇，過之，飛鳥離之，兇。是謂災眚。象曰：「弗遇過之」，已亢也。上六，「艮」也。以陰居柔，而在上卦之上，乘六五之「巽」，而應乎九三。三，「震」「兌」也，故曰：「弗遇，過之。」上六之於六五，宜若遇矣。然二爻皆陰，無相與之意，上又偏勝，而應在九三，月乘陵六五之象，是以「弗遇」而「過之」也。或曰：六二之於初六，其乘陵之象與？五上，君也，而爻謂之遇，何哉？曰：六二，臣也；初六亦臣也。同類而相從，斯謂之遇也。六五，君也，而上六乘之。天無二日，民無二王，謂之「遇」則可乎？是以謂之「過」也。故曰：「飛鳥離之，兇。」「離」，麗也。詩云「雉離於羅」是也。上六翰飛極高，而其體「艮」，「艮」為止，故有網羅之象焉。然初上皆「艮」也，初六言「飛鳥以兇」，而此言「離之兇」者，初辭擬之，卒成之終也，故曰「是謂災眚」。「災」，天降也；「眚」，人為也。當小過之時，居窮上之勢，難至無日矣。謂之災，則有人為之咎焉；謂之眚，則有天降之罰焉。是則人禍天刑相因而猝至，不可逃也。復之上六曰：「迷復，兇，有災眚。」與此同義。故子曰：「弗遇過之，已亢也。」亢則不與之遇而過之矣。或曰：揚雄有言：「鴻飛冥冥，戈人何慕？」鳥飛愈高，則矰繳所不能及，何以反離於兇乎？曰：物之大小，皆有定分，分有所止，力有所窮，鳥飛愈高，其勢必不能久，是以至於離兇也。乾之九五曰：「飛龍在天。」上九曰：「亢龍有悔。」夫龍，陽物也，升潛變化，不可制畜者也。飛而在天，然且亢而有悔，況飛鳥乎！然則揚雄所謂「鴻飛冥冥」，以譬君子遠人而闢患，良非善喻者也。若易之取象，則豈云爾哉？其在漸曰：「鴻漸於磐，飲食衎衎。」斯其所以為全身遠害者與！周易經傳集解卷三十一，",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
